// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface PackUseIn {
  pack_code: string;
  /** The operation (the theatre) */
  booking_id?: number | null;
  /** A procedure on the ward */
  admission_id?: number | null;
}

export interface PackOut {
  pack_id: number;
  pack_code: string;
  set_type_id: number;
  set_code: string;
  set_name: string;
  cycle_id: number;
  cycle_number: string;
  cycle_status: "Running" | "Quarantined" | "Released" | "Failed" | "Recalled";
  sterilized_on: string;
  expires_on: string;
  status: "Quarantined" | "Available" | "Issued" | "Used" | "Expired" | "Failed" | "Recalled";
  issued_at: string | null;
  issued_by_name: string | null;
  issued_to_ward_id: number | null;
  issued_to_ward_name: string | null;
  issued_to_ot_id: number | null;
  issued_to_ot_name: string | null;
  used_at: string | null;
  used_by_name: string | null;
  patient_id: number | null;
  mrn: string | null;
  patient_name: string | null;
  booking_id: number | null;
  booking_number: string | null;
  admission_id: number | null;
  admission_number: string | null;
  row_version: number;
  /** Expires within cssd_expiry_alert_days: use it first */
  expiring_soon: boolean;
}

/** A sterile pack opened for a patient — POST /api/v1/cssd/packs/use (who may call: holders of cssd.pack.use). */
export function usePack(body: PackUseIn): Promise<PackOut> {
  return api<PackOut>("POST", `/cssd/packs/use`, body);
}

/** One sterile pack (scan its label) — GET /api/v1/cssd/packs/{pack_code} (who may call: holders of cssd.view or cssd.operate or cssd.manage or cssd.pack.use). */
export function getPack(pack_code: string): Promise<PackOut> {
  return api<PackOut>("GET", `/cssd/packs/${pack_code}`, undefined);
}

/** Sterile packs (the stock) — GET /api/v1/cssd/packs (who may call: holders of cssd.view or cssd.operate or cssd.manage or cssd.pack.use). */
export function listPacks(query?: { status?: "Quarantined" | "Available" | "Issued" | "Used" | "Expired" | "Failed" | "Recalled" | null; set_type_id?: number | null; ward_id?: number | null; ot_id?: number | null; expiring_only?: boolean; limit?: number }): Promise<PackOut[]> {
  return api<PackOut[]>("GET", withQuery(`/cssd/packs`, query), undefined);
}
